// Roz 10 "Discovered + Exact" candidates chuno (ServiceNow / AI_ML baari-baari), open_to_work wale pehle
const LIMIT = 25;
const take = (node, tab) => $(node).all().map(i => i.json)
  .filter(r => r.linkedin_url && r.readiness === 'Discovered' && r.title_match === 'Exact')
  .sort((a, b) => (b.open_to_work === 'Yes') - (a.open_to_work === 'Yes') || String(a.first_seen).localeCompare(String(b.first_seen)))
  .map(r => ({ tab, row: r }));
const sn = take('Read ServiceNow rows', 'ServiceNow'), ai = take('Read AI_ML rows', 'AI_ML');
const picks = [];
while (picks.length < LIMIT && (sn.length || ai.length)) {
  if (sn.length) picks.push(sn.shift());
  if (picks.length < LIMIT && ai.length) picks.push(ai.shift());
}
if (!picks.length) return [];
return [{ json: { picks, urls: picks.map(p => p.row.linkedin_url.replace('://in.linkedin.com', '://www.linkedin.com')) } }];

// LinkedIn profile data -> row update (linkedin_url se match hoga)
const picks = $('Pick 10 candidates').first().json.picks;
const profiles = $input.all().map(i => i.json).filter(p => p && (p.linkedinUrl || p.originalQuery));
const now = new Date(Date.now() + 5.5 * 3600e3);
const today = now.toISOString().slice(0, 10), stamp = now.toISOString().slice(0, 16).replace('T', ' ');
const MON = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };
const POOL_RX = { ServiceNow: /service\s?now|\bsnow\b|\bitsm\b|\bitom\b|\bcmdb\b/i,
  AI_ML: /machine learning|\bml\b|\bai\b|artificial intelligence|gen\s?ai|generative|\bllms?\b|data scien|computer vision|\bnlp\b|deep learning|mlops|agentic/i };
const MOD = { ServiceNow: [['ITSM', /\bitsm\b|incident|service catalog|change management/i], ['ITOM', /\bitom\b|discovery|event management/i], ['CMDB', /\bcmdb\b/i],
  ['HRSD', /\bhrsd\b|hr service/i], ['CSM', /\bcsm\b|customer service management/i], ['SecOps', /secops|security operations/i], ['ITAM/SAM', /\bitam\b|\bsam\b|asset management/i],
  ['GRC/IRM', /\bgrc\b|\birm\b/i], ['ITBM/SPM', /\bitbm\b|\bspm\b|\bppm\b/i], ['Service Portal', /service portal/i], ['Integrations', /integration|rest api|scripted rest/i], ['Flow Designer', /flow designer/i]],
  AI_ML: [['GenAI', /gen\s?ai|generative/i], ['LLMs', /\bllms?\b|large language/i], ['RAG', /\brag\b|retrieval/i], ['Agentic AI', /agentic|ai agents?|multi-agent|langgraph/i],
  ['Computer Vision', /computer vision|opencv|yolo|image/i], ['NLP', /\bnlp\b|natural language|bert/i], ['MLOps', /mlops|mlflow|kubeflow/i], ['Data Science', /data scien/i], ['Deep Learning', /deep learning|pytorch|tensorflow|keras/i]] };
const slug = u => (String(u || '').match(/linkedin\.com\/in\/([^/?#]+)/i) || [])[1]?.toLowerCase();
const ym = d => d && d.year ? d.year * 12 + (MON[String(d.month || 'jan').slice(0, 3).toLowerCase()] ?? 0) : null;
const nowM = now.getUTCFullYear() * 12 + now.getUTCMonth();
function months(list) {           // overlap merge
  const iv = list.map(([s, e]) => [s, e]).filter(([s, e]) => s != null && e != null && e >= s).sort((a, b) => a[0] - b[0]);
  let total = 0, cur = null;
  for (const [s, e] of iv) { if (!cur || s > cur[1]) { if (cur) total += cur[1] - cur[0]; cur = [s, e]; } else cur[1] = Math.max(cur[1], e); }
  if (cur) total += cur[1] - cur[0];
  return total;
}
const yrs = m => Math.round(m / 12 * 10) / 10;
const out = [];
let emailsValid = 0, emailsRisky = 0, phones = 0, rejected = 0;
const found = new Set();
for (const p of profiles) {
  const s = slug(p.linkedinUrl) || slug(p.originalQuery && p.originalQuery.query);
  const pk = picks.find(x => slug(x.row.linkedin_url) === s);
  if (!pk) continue;
  found.add(s);
  const tab = pk.tab, r = pk.row;
  const exp = (p.experience || []).map(e => ({ ...e, s: ym(e.startDate), e: /present/i.test(e.endDate?.text || '') || !e.endDate ? nowM : ym(e.endDate) }));
  const cur = exp.find(e => /present/i.test(e.endDate?.text || '') || !e.endDate) || exp[0] || {};
  const about = String(p.about || '');
  const totalStated = (about.match(/(\d{1,2})\+?\s*(?:years|yrs)\s*(?:of\s*)?(?:total|overall)?\s*(?:IT\s*)?(?:experience|exp)/i) || [])[1];
  const calc = exp.length ? yrs(months(exp.map(e => [e.s, e.e]))) : '';
  const total = totalStated && (calc === '' || Number(totalStated) > calc) ? Number(totalStated) : calc;   // About mein likha zyada ho to wahi
  const dom = exp.filter(e => POOL_RX[tab].test(`${e.position || ''} ${e.description || ''} ${(e.skills || []).join(' ')}`));
  const domain = dom.length ? yrs(months(dom.map(e => [e.s, e.e]))) : '';
  const bucket = domain === '' ? 'Unknown' : domain < 2 ? '0-2' : domain < 5 ? '2-5' : domain < 8 ? '5-8' : '8+';
  const skills = (p.skills || []).map(x => x.name).filter(Boolean);
  const blob = `${p.headline || ''} ${about} ${skills.join(' ')} ${exp.map(e => `${e.position || ''} ${e.description || ''}`).join(' ')}`;
  const mods = MOD[tab].filter(([, rx]) => rx.test(blob)).map(([m]) => m);
  const certs = [...new Set([...(p.certifications || []).map(c => c.title).filter(Boolean),
    ...((blob.match(/\b(CSA|CAD|CTA|CIS[- ]?[A-Z]{2,5})\b/g) || []).map(x => `ServiceNow ${x.toUpperCase()}`))])].slice(0, 6);
  const loc = String(p.location?.linkedinText || '');
  const inIndia = p.location?.countryCode === 'IN' || /india/i.test(loc) || (!loc.trim() && !p.location?.countryCode);
  const fits = POOL_RX[tab].test(blob);
  const emails = (p.emails || []).filter(e => e.email).sort((a, b) => (b.status === 'valid') - (a.status === 'valid') || (b.qualityScore || 0) - (a.qualityScore || 0));
  const em = emails[0];
  let email = r.email || '', emailStatus = r.email_status || 'Not found';
  if (!email && em) {
    email = em.email;
    const local = em.email.split('@')[0].toLowerCase(), fn = String(r.name || '').split(' ')[0].toLowerCase();
    const guess = local.length <= 12 && !/[._-]/.test(local) && (local === fn || String(r.name || '').toLowerCase().split(' ').includes(local));
    emailStatus = (em.status === 'valid' ? `Valid (score ${em.qualityScore ?? '-'})` : em.status === 'risky' || em.catchAllDomain ? `Risky (catch-all, score ${em.qualityScore ?? '-'})` : 'Invalid')
      + (guess ? ' - check: may be a pattern guess' : '');
    if (em.status === 'valid') emailsValid++; else emailsRisky++;
  }
  const edu = (p.education || []).slice(0, 2).map(e => [e.degree, e.fieldOfStudy, e.schoolName, e.period].filter(Boolean).join(', ')).join(' | ');
  const notesOld = String(r.notes || '');
  const titleNow = cur.position || r.current_title;
  const row = { linkedin_url: r.linkedin_url, last_updated: today };
  if (!inIndia || !fits) {
    rejected++;
    Object.assign(row, { readiness: 'Rejected', notes: `${notesOld}; Rejected ${today}: ${!inIndia ? 'not in India (' + loc.trim() + ')' : 'profile is not ' + tab + ' work'}`.replace(/^; /, '') });
  } else {
    Object.assign(row, {
      headline: p.headline || r.headline, current_title: titleNow, current_company: cur.companyName || r.current_company,
      total_experience_years: total, [tab === 'ServiceNow' ? 'servicenow_experience_years' : 'ai_ml_experience_years']: domain,
      experience_bucket: bucket, [tab === 'ServiceNow' ? 'modules' : 'specialization']: mods.join('; '), certifications: certs.join('; '),
      skills: skills.slice(0, 12).join('; '), open_to_work: p.openToWork ? 'Yes' : 'No',
      seniority: /\bintern\b/i.test(titleNow) ? 'Intern' : /\b(head|director|manager)\b/i.test(titleNow) ? 'Manager' : /\b(lead|principal|staff|architect)\b/i.test(titleNow) ? 'Lead'
        : total !== '' && total >= 5 ? 'Senior' : total !== '' && total < 2 ? 'Junior' : 'Mid',
      past_employers: exp.filter(e => e !== cur).slice(0, 5).map(e => `${e.companyName || ''} (${e.startDate?.year || ''}-${e.endDate?.year || ''})`).join('; '),
      email, email_status: emailStatus, contact_source: r.contact_source || (email ? 'Apify LinkedIn profile scraper' : ''),
      readiness: 'Enriched', notes: [notesOld, edu && `Edu: ${edu}`, `Full profile scraped ${today} (n8n)`].filter(Boolean).join('; '),
    });
  }
  out.push({ json: { _tab: tab, ...row } });
}
for (const pk of picks) if (!found.has(slug(pk.row.linkedin_url)))
  out.push({ json: { _tab: pk.tab, linkedin_url: pk.row.linkedin_url, last_updated: today, notes: `${pk.row.notes || ''}; profile scrape failed ${today}`.replace(/^; /, '') } });
const stats = { stamp, requested: picks.length, enriched: out.filter(o => o.json.readiness === 'Enriched').length, rejected, emailsValid, emailsRisky, phones, failed: picks.length - found.size };
return out.map((o, i) => (i === 0 ? { json: { ...o.json, _stats: stats } } : o));

const s = $input.first().json._stats;
return [{ json: { 'Run date': s.stamp, 'Flow': 'n8n (enrichment)', 'Queries': 0, 'Google results': '', 'LinkedIn profiles found': s.requested,
  'Rejected (not India / wrong title / duplicate)': s.rejected, 'New rows added': `${s.enriched} enriched`,
  'Apify cost ($)': Math.round(s.requested * 0.01 * 100) / 100,
  'Notes': `Emails: ${s.emailsValid} valid, ${s.emailsRisky} risky. Scrape failed: ${s.failed}. Actor harvestapi/linkedin-profile-scraper.` } }];
